namespace OCP\EventDispatcher { class Event {} interface IEventListener{public function handle(Event $event):void;} }
namespace OCA\FlzPermissionMatrix\PublicApi\V1 {
 interface PermissionProvider{public function descriptor():PermissionProviderDescriptor;public function collect():PermissionProviderResult;} final class PermissionProviderDescriptor{public function __construct(...$a){}} final class PermissionCondition{private function __construct(public string $operator,public array $children=[],public ?string $groupId=null){}public static function group(string $groupId):self{return new self('group',[],$groupId);}public static function self():self{return new self('self');}public static function nextcloudAdmin():self{return new self('nextcloud-admin');}public static function temporaryAppAdminGrant():self{return new self('app-admin-grant');}public static function all(array $children):self{return new self('all',$children);}public static function any(array $children):self{return new self('any',$children);}} final class PermissionRule{public function __construct(public string $type,public string $name,public string $detail,public string $permission,public string $label,public string $effect,public string $scope,public PermissionCondition $condition,public string $source,public string $confidence){}} final class PermissionProviderResult{public function __construct(public array $rules,public bool $complete=true,public array $warnings=[]){}} final class RegisterPermissionProvidersEvent extends \OCP\EventDispatcher\Event{public array $providers=[];public function register(PermissionProvider $p):void{$this->providers[]=$p;}}
}
namespace OCA\FlzRoom\Service { final class RoomPermissionPolicyService{public const ROOM_READ='room.read';public const BOOKING_MANAGE_OWN='booking.manage-own';public const BOOKING_TITLE_READ='booking.title.read';public const BOOKING_INTERVENE_FOREIGN='booking.intervene-foreign';public const ROOM_MANAGE='room.manage';public function groupIdsFor(string $permission):array{return match($permission){self::ROOM_READ,self::BOOKING_MANAGE_OWN,self::BOOKING_TITLE_READ=>['flz-PFK','flz-Sekretariat'],self::BOOKING_INTERVENE_FOREIGN=>['flz-Sekretariat','flz-BL'],self::ROOM_MANAGE=>['flz-Sekretariat'],default=>[]};}} final class TemporaryAdminAccessService{public const GRANT_MANAGER_GROUP='Datenschutzbeauftragte';} }
