 $provider=new RoomPermissionProvider(new OCA\FlzRoom\Service\RoomPermissionPolicyService());$rules=$provider->collect()->rules;$byPermission=[];foreach($rules as $rule)$byPermission[$rule->permission]=$rule;
 if(array_keys($byPermission)!==['room.read','booking.manage-own','booking.title.read','booking.intervene-foreign','booking.intervention-audit.read','booking.manage-all','room.manage','permission.assignments.manage','retention.manage','temporary-admin.manage'])throw new RuntimeException('Der Raumrechtevertrag beschreibt die zehn getrennten Berechtigungen nicht vollständig.');
 if(array_map(fn($child)=>$child->groupId,$byPermission['booking.intervene-foreign']->condition->children)!==['flz-Sekretariat','flz-BL'])throw new RuntimeException('Der Fremdeingriff folgt nicht der semantischen Rechtezuordnung.');
 if($byPermission['booking.intervention-audit.read']->condition->groupId!=='Datenschutzbeauftragte')throw new RuntimeException('Das Eingriffsaudit ist nicht ausschließlich Datenschutzbeauftragte zugeordnet.');
 $read=$byPermission['room.read']->condition;
 if($read->operator!=='any'||array_map(fn($child)=>$child->operator,$read->children)!==['group','group','all']||array_map(fn($child)=>$child->groupId,array_slice($read->children,0,2))!==['flz-PFK','flz-Sekretariat'])throw new RuntimeException('Der Lesescope folgt nicht den semantischen Rollenrechten und dem zeitweisen Adminpfad.');
 if(array_map(fn($child)=>$child->operator,$read->children[2]->children)!==['nextcloud-admin','app-admin-grant'])throw new RuntimeException('Die zeitgebundene Adminbedingung ist unvollständig.');
 $title=$byPermission['booking.title.read']->condition;
 if($title->operator!=='any'||array_map(fn($child)=>$child->groupId,$title->children)!==['flz-PFK','flz-Sekretariat'])throw new RuntimeException('Freititel folgen nicht dem eigenständigen Rollenrecht.');
 if(array_map(fn($child)=>$child->operator,$byPermission['booking.manage-all']->condition->children)!==['nextcloud-admin','app-admin-grant'])throw new RuntimeException('Die zeitgebundene Adminbedingung ist unvollständig.');
 if(array_map(fn($child)=>$child->operator,$byPermission['room.manage']->condition->children)!==['group','nextcloud-admin'])throw new RuntimeException('Raumverwaltung trennt Sekretariat und nativen Adminpfad nicht.');
 foreach(['permission.assignments.manage','retention.manage','temporary-admin.manage'] as $permission)if($byPermission[$permission]->condition->groupId!=='Datenschutzbeauftragte')throw new RuntimeException("Datenschutzrecht {$permission} ist nicht fest zugeordnet.");
 $event=new RegisterPermissionProvidersEvent();$listener=new RoomPermissionProviderListener($provider);if(!$listener instanceof \OCP\EventDispatcher\IEventListener)throw new RuntimeException('Permission-Listener erfüllt den Nextcloud-Eventvertrag nicht.');$listener->handle($event);if(($event->providers[0]??null)!==$provider)throw new RuntimeException('Lazy-Registrierung fehlt.');echo "Room permission provider tests passed\n";
